from collections import deque

def shortestBridge(grid):
    n = len(grid)
    directions = [(-1,0), (1,0), (0,-1), (0,1)]  # up, down, left, right

    def dfs(x, y, island):
        # Standard DFS to mark the first island as 2
        if x < 0 or x >= n or y < 0 or y >= n or grid[x][y] != 1:
            return
        grid[x][y] = 2
        island.append((x, y))
        for dx, dy in directions:
            dfs(x + dx, y + dy, island)

    # 1. Find the first island and mark it as 2, collect its boundary
    found = False
    island = []
    for i in range(n):
        if found:
            break
        for j in range(n):
            if grid[i][j] == 1:
                dfs(i, j, island)
                found = True
                break

    # 2. BFS from all boundary cells of the first island
    q = deque(island)
    steps = 0

    while q:
        for _ in range(len(q)):
            x, y = q.popleft()
            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if 0 <= nx < n and 0 <= ny < n:
                    if grid[nx][ny] == 1:
                        return steps
                    if grid[nx][ny] == 0:
                        grid[nx][ny] = 2  # mark as visited
                        q.append((nx, ny))
        steps += 1
